INSERT INTO `berita` (`id`, `title`, `slug`, `content`, `image`, `category_id`, `user_id`, `is_published`, `published_at`, `created_at`, `updated_at`) VALUES
(1, 'Santri Nurur Rahmah Raih Juara Musabaqah Hifzhil Qur\'an Tingkat Kabupaten', 'santri-nurur-rahmah-juara-mhq-kabupaten', 'Prestasi membanggakan datang dari cabang hifzhil Qur\'an. Tiga santri Pondok Pesantren Nurur Rahmah berhasil membawa pulang juara satu, dua, dan harapan satu pada Musabaqah Hifzhil Qur\'an tingkat Kabupaten Probolinggo.\n\nKeberhasilan ini merupakan buah dari pembinaan halaqah tahfidz yang konsisten, muraja\'ah harian, serta dukungan penuh dari para asatidz dan orang tua santri.\n\nPesantren mengucapkan terima kasih atas doa dan dukungan seluruh keluarga besar Nurur Rahmah. Semoga prestasi ini menjadi pemacu semangat untuk terus menjaga dan mengamalkan Al-Qur\'an.', 'images/news-1.jpg', 3, 1, 1, '2026-11-01 19:53:51', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(2, 'Pendaftaran Santri Baru Tahun Ajaran 2027/2028 Resmi Dibuka', 'pendaftaran-santri-baru-2027-2028-dibuka', 'Pendaftaran santri baru tahun ajaran 2027/2028 resmi dibuka. Gelombang pertama dibuka dengan kuota terbatas dan akan ditutup setelah kuota terpenuhi.\n\nCalon santri dapat mendaftar secara online melalui situs pesantren maupun langsung datang ke kantor pendaftaran. Berkas yang perlu disiapkan meliputi fotokopi akta kelahiran, kartu keluarga, rapor terakhir, dan pasfoto.\n\nInformasi lebih lanjut mengenai biaya, jadwal seleksi, dan persyaratan dapat menghubungi panitia PPDB melalui WhatsApp resmi pesantren.', 'images/news-2.jpg', 1, 1, 1, '2026-10-17 19:53:51', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(3, 'Kajian Rutin Kitab Akhlak: Menanamkan Adab Sejak Dini', 'kajian-rutin-kitab-akhlak', 'Majelis kajian kitab akhlak kembali digelar di masjid pesantren. Kegiatan ini menghadirkan pengasuh dan para asatidz untuk meneguhkan pentingnya adab dalam menuntut ilmu.\n\nSantri diajak memahami bahwa ilmu yang bermanfaat selalu lahir dari adab yang dijaga. Melalui kajian ini, diharapkan para santri tumbuh menjadi pribadi yang santun, disiplin, dan menghormati guru serta sesama.\n\nKajian rutin ini terbuka bagi santri dan masyarakat sekitar yang ingin menimba ilmu bersama.', 'images/news-3.jpg', 4, 1, 1, '2026-10-02 19:53:51', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(4, 'Wisuda Tahfidz Angkatan XII: 48 Santri Khatam 30 Juz', 'wisuda-tahfidz-angkatan-xii', 'Pondok Pesantren Nurur Rahmah menggelar wisuda tahfidz angkatan XII. Sebanyak 48 santri dinyatakan khatam 30 juz setelah melalui proses setoran dan tasmi\'.\n\nProsesi wisuda dihadiri oleh pengasuh, dewan asatidz, orang tua santri, serta tamu undangan. Suasana haru menyelimuti acara ketika para santri menerima syahadah hafalan.\n\nPengasuh berpesan agar hafalan yang telah diraih senantiasa dijaga melalui muraja\'ah dan diamalkan dalam kehidupan sehari-hari.', 'images/news-4.jpg', 2, 1, 1, '2026-09-17 19:53:51', '2026-11-06 19:53:51', '2026-11-06 19:53:51');

