INSERT INTO `kegiatan` (`id`, `title`, `slug`, `description`, `icon_or_image`, `category`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Tahfidz Al-Qur\'an', 'tahfidz-al-quran', 'Program unggulan dengan halaqah kecil, target hafalan terukur, dan bimbingan muraja\'ah harian agar hafalan santri mutqin sekaligus terjaga.', 'images/program-tahfidz.jpg', 'tahfidz', 1, '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(2, 'Kajian Kitab Kuning', 'kajian-kitab-kuning', 'Kajian turats dengan metode sorogan dan bandongan, membangun pemahaman agama yang berakar pada tradisi ulama dan relevan dengan zaman.', 'images/program-kitab.jpg', 'kitab_kuning', 1, '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(3, 'Pendidikan Formal', 'pendidikan-formal', 'Madrasah dan sekolah formal yang memadukan kurikulum nasional dengan nilai pesantren, menyiapkan santri untuk melanjutkan ke jenjang perguruan tinggi.', 'images/program-formal.jpg', 'formal', 1, '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(4, 'Ekstrakurikuler & Kemandirian', 'ekstrakurikuler-kemandirian', 'Ruang berekspresi dan berorganisasi untuk menumbuhkan percaya diri, kepemimpinan, dan keterampilan hidup yang seimbang dengan adab.', 'images/program-ekskul.jpg', 'ekstrakurikuler', 1, '2026-11-06 19:53:51', '2026-11-06 19:53:51');

