INSERT INTO `site_settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES
(1, 'hero_title', 'Membentuk generasi Qur\'ani, berakhlak mulia, siap berkarya.', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(2, 'hero_subtitle', 'Pondok Pesantren Nurur Rahmah memadukan tahfidz Al-Qur\'an, kajian kitab kuning, dan pendidikan formal dalam lingkungan yang hangat dan penuh keberkahan.', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(3, 'hero_year', '1998', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(4, 'target_juz', '30', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(5, 'total_santri', '480', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(6, 'total_pengajar', '36', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(7, 'history', 'Berdiri sejak 1998, Pondok Pesantren Nurur Rahmah tumbuh dari sebuah majelis kecil di Probolinggo menjadi pesantren yang memadukan tahfidz Al-Qur\'an, kajian kitab kuning, dan pendidikan formal. Kami percaya bahwa ilmu yang bermanfaat lahir dari adab yang dijaga dan lingkungan yang hangat.', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(8, 'vision', 'Menjadi pesantren rujukan yang melahirkan generasi Qur\'ani, berakal terbuka, berakhlak mulia, dan mandiri dalam berkarya.', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(9, 'missions', 'Menyelenggarakan pendidikan tahfidz dan diniyah yang mutqin serta menyenangkan.\nMemadukan kajian turats dengan kompetensi akademik dan literasi modern.\nMenumbuhkan adab, kemandirian, dan kepedulian sosial melalui keteladanan.\nMembangun lingkungan pesantren yang aman, bersih, dan penuh keberkahan.', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(10, 'leader_name', 'KH. Ahmad Fauzi Abdurrahman', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(11, 'leader_title', 'Pengasuh Pondok Pesantren Nurur Rahmah', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(12, 'leader_quote', 'Pendidikan terbaik adalah yang menumbuhkan iman, ilmu, dan adab sekaligus. Kami menemani setiap santri untuk tumbuh dengan tenang, terarah, dan penuh keberkahan.', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(13, 'leader_photo', 'images/pengasuh.jpg', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(14, 'leader_since', 'Mengasuh sejak 1998', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(15, 'address', 'Krajan, Sambirampak Lor, Kec. Kotaanyar, Kabupaten Probolinggo, Jawa Timur 67293', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(16, 'whatsapp', '+62 812-3456-7890', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(17, 'email', 'kreseknururrahmah@gmail.com', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(18, 'operational_hours', 'Senin – Sabtu, 08.00 – 16.00 WIB', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(19, 'maps_embed', 'https://www.google.com/maps?q=-7.7738738,113.5466582&z=16&output=embed', '2026-11-06 19:53:51', '2026-11-06 19:53:51'),
(20, 'site_logo', 'images/logo.png', '2026-11-07 03:37:47', '2026-11-07 05:39:21');

